INSERT INTO `email_templates` (`id`, `slug`, `name`, `subject`, `details`, `content`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'transaction_pending', 'Transaksi Pending', 'Menunggu Pembayaran #{order_id}', '_Variables: {order_id}, {nickname}, {product}, {amount}, {status}_', '<p>Halo <strong>{nickname}</strong>,</p><p>Terima kasih telah melakukan pemesanan.</p><p>Berikut adalah detail pesanan Anda:</p><ul><li>No Invoice: <strong>{order_id}</strong></li><li>Produk: {product}</li><li>Nominal: {amount}</li><li>Status: <strong>{status}</strong></li></ul><p>Silakan selesaikan pembayaran agar pesanan dapat diproses otomatis.</p><p>Terima Kasih,<br>TopUpIndo</p>', 1, '2026-02-08 11:07:39', '2026-02-08 11:07:39'),
(2, 'transaction_success', 'Transaksi Sukses', 'Pesanan Berhasil #{order_id}', '_Variables: {order_id}, {nickname}, {product}, {amount}, {sn}, {note}_', '<p>Halo <strong>{nickname}</strong>,</p><p>Pesanan Anda telah berhasil diproses.</p><p>Detail Pesanan:</p><ul><li>No Invoice: <strong>{order_id}</strong></li><li>Produk: {product}</li><li>SN/Kode: <strong>{sn}</strong></li><li>Status: <strong>Success</strong></li></ul><p>{note}</p><p>Terima kasih telah berbelanja.</p>', 1, '2026-02-08 11:07:39', '2026-02-08 11:07:39'),
(3, 'transaction_failed', 'Transaksi Gagal', 'Pesanan Gagal #{order_id}', '_Variables: {order_id}, {nickname}, {product}, {amount}, {note}_', '<p>Halo <strong>{nickname}</strong>,</p><p>Mohon maaf, pesanan Anda gagal atau dibatalkan.</p><p>Detail Pesanan:</p><ul><li>No Invoice: <strong>{order_id}</strong></li><li>Produk: {product}</li><li>Status: <strong>Failed</strong></li></ul><p>Alasan: {note}</p><p>Silakan hubungi Admin jika ada kendala.</p>', 1, '2026-02-08 11:07:39', '2026-02-08 11:07:39');
