(37, 'INDOSAT', 'Paket Data Indosat', 'paket-indosat', NULL, 'active', '/assets/thumbnail/indosat.png', '/assets/banner_game/indosat.png', 'pulsa', NULL, NULL, NULL, 0, NULL, '&lt;p&gt;Cara Order:&lt;/p&gt;&lt;ol&gt;&lt;li&gt;Masukkan nomor Indosat anda&lt;/li&gt;&lt;li&gt;Pilih jumlah pulsa yang diinginkan&lt;/li&gt;&lt;li&gt;Pilih metode pembayaran&lt;/li&gt;&lt;li&gt;Masukkan nomor whatsapp&lt;/li&gt;&lt;li&gt;Klik beli sekarang dan lakukan pembayaran&lt;/li&gt;&lt;li&gt;Pulsa akan masuk otomatis&lt;/li&gt;&lt;/ol&gt;&lt;p&gt;Informasi&lt;br&gt;Harap periksa kembali nomor anda&lt;br&gt;Kesalahan penulisan nomor mutlak tanggung jawab anda sebagai pembeli&lt;/p&gt;', '0857*******', NULL, NULL, NULL, NULL, '2025-05-02 11:17:16', '2025-05-02 11:18:16', 4),
(38, 'TELKOMSEL', 'pulsa telkomsel', 'pulsa-telkomsel', NULL, 'active', '/assets/thumbnail/logo-telkomsel.webp', '/assets/banner_game/logo-telkomsel.webp', 'pulsa', NULL, NULL, NULL, 0, NULL, '&lt;h3&gt;🔥 PAKET PULSA TELKOMSEL MURAH &amp;amp; CEPAT! 🔥&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Top Up Pulsa Telkomsel Anti Ribet &amp;amp; Langsung Masuk!&lt;/strong&gt;&lt;/p&gt;&lt;p&gt;🔹 Tersedia nominal:&lt;br&gt;– 5.000 | 10.000 | 15.000 | 20.000 | 25.000 | 50.000 | 100.000&lt;br&gt;🔹 Harga bersaing &amp;amp; lebih murah dari konter!&lt;br&gt;🔹 Pulsa masuk dalam hitungan detik-menit&lt;br&gt;🔹 Cocok untuk isi ulang harian, emergency, atau hadiah teman&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Kelebihan beli di sini:&lt;/strong&gt;&lt;br&gt;✅ Fast respon &amp;amp; layanan ramah&lt;br&gt;✅ Bisa order 24 jam&lt;br&gt;✅ Aman &amp;amp; terpercaya&lt;br&gt;✅ Cocok untuk reseller&lt;/p&gt;&lt;p&gt;🛒 &lt;i&gt;Langsung order sekarang dan rasakan layanan cepat &amp;amp; terpercaya dari kami!&lt;/i&gt;&lt;/p&gt;', '082189093929', NULL, NULL, NULL, NULL, '2025-05-08 14:17:37', '2025-05-08 14:21:13', 4),
(39, 'ROBLOX', 'Roblox Corporation', '12345678', NULL, 'active', '/assets/thumbnail/990127e0fef488963ad7273041618b7ce099a3ee.png', '/assets/banner_game/c57a819ba0f3587ce92c372df48a3fe7df761c78.png', 'populer', NULL, NULL, NULL, 0, NULL, '&lt;p&gt;&lt;strong&gt;Top Up Robux? Di Sini Aja!&lt;/strong&gt;&lt;br&gt;Mau beli Robux cepet, murah, dan gak ribet? Di sini tempatnya! Cukup masukin username kamu, pilih jumlah Robux, bayar, dan duduk manis — Robux langsung meluncur ke akunmu!&lt;/p&gt;&lt;p&gt;💸 Murah meriah&lt;br&gt;⚡ Super cepat&lt;br&gt;🔒 Aman dan terpercaya&lt;br&gt;📱 Bayar pake e-wallet, pulsa, atau transfer bank&lt;/p&gt;&lt;p&gt;Main Roblox makin seru kalau Robux kamu banyak! Yuk top up sekarang di [Nama Web Kamu]&lt;/p&gt;', 'ID : 1234567', NULL, NULL, NULL, NULL, '2025-09-04 03:46:12', '2025-09-04 03:59:29', 1);
