(1, 'transaction_pending', 'Transaksi Pending', '_Variables: {order_id}, {nickname}, {product}, {amount}, {status}_', '*Konfirmasi Pesanan*\n\nTerima kasih telah melakukan pemesanan di *IstanaTopup*.\n\nNo Invoice: *{order_id}*\nProduk: *{product}*\nNominal: *{amount}*\nStatus: *{status}*\n\nSilakan selesaikan pembayaran agar pesanan dapat diproses otomatis.\n\nTerima Kasih,\nIstanaTopup', 1, '2026-02-07 11:54:59', '2026-02-07 13:37:35'),
(2, 'transaction_success', 'Transaksi Sukses', '_Variables: {order_id}, {nickname}, {product}, {amount}, {sn}_', '*Pesanan Sukses!*\n\nHalo *{nickname}*,\nPesanan kamu telah berhasil diproses:\n\nNo Invoice: *{order_id}*\nProduk: *{product}*\nSN/Kode: *{sn}*\n\nTerima kasih telah berbelanja di *TopUpIndo*.\nJangan lupa simpan bukti transaksi ini.', 1, '2026-02-07 11:54:59', '2026-02-07 11:54:59'),
(3, 'transaction_failed', 'Transaksi Gagal / Batal', '_Variables: {order_id}, {nickname}, {product}, {reason}_', '*Pesanan Dibatalkan*\n\nMohon maaf, pesanan dengan No Invoice: *{order_id}* telah dibatalkan.\n\nAlasan: {reason}\n\nSilakan hubungi Admin jika saldo terpotong namun transaksi gagal.\n\nTerima Kasih,\nTopUpIndo', 1, '2026-02-07 11:54:59', '2026-02-07 11:54:59');
